import axios from "axios";

const API = axios.create({
  baseURL: "http://localhost:5000/api", // backend port
});

// Upload meeting file
export const uploadMeeting = (formData) =>
  API.post("/ai/upload", formData, {
    headers: { "Content-Type": "multipart/form-data" },
  });

// Process transcript
export const processTranscript = (transcript) =>
  API.post("/ai/process", { transcript });

// Start live bot
export const startLiveBot = (meetingLink) =>
  API.post("/livebot/start", { meetingLink });

// Download PDF
export const downloadPDF = (data) =>
  API.post("/pdf/download", data, {
    responseType: "blob",
  });
